    short nRole;            /* 0x98 */
    short nPhase;           /* 0x9A */
    int oid;                /* 0x9C */
    char padA0[8];
    union { XF *pxfRef; float gA8; };   /* 0xA8 */
    char padAC[0xD0 - 0xAC];
    int nD0;                /* 0xD0 */
    float *pgD4;            /* 0xD4 */
