static __inline__ void PingPong(ASEGA *p, float *pt, float *pdt, float tMax, float t2)
{
    *pdt = __builtin_fabsf(*pdt);
    p->svtRate = __builtin_fabsf(p->svtRate);
    if (tMax <= *pt) {
        *pt = t2 - *pt;
        *pdt = -*pdt;
        p->svtRate = -p->svtRate;
    }
}
/** @sly2-annot addr=0x1317D8
 * Purpose: Wraps/ping-pongs the ASEGA time at segment end (fmodf, GModPositive)
 * Info: proposed name FWrapAsegaTime (T1); TU asega
 * Notes: names_v2 v1 proposed RetractAsega__FP5ASEGA (0.171)
 * Confidence: mid (draft) [T1 0.70] - evidence: static naming pass; sources: r1_116918
 * See: docs/engine/animation.md#7-key-functions,
 *   docs/reference/functions/animation.md#asega-0x1308a8-0x131f70
 * @end-sly2-annot */
int FWrapAsegaTime(ASEGA *p, float *pt, float *pdt)
{
    float tMax = p->paseg->tMax;
    float t = *pt;
    int f = 0;
    if (tMax <= t) {
        if (0.0f < *pdt)
            f = 1;
        if (p->grfapl & 8) {
            *pt = fmodf(t, tMax);
        } else if (p->grfapl & 0x10) {
            float t2 = tMax + tMax;
            *pt = fmodf(t, t2);
            PingPong(p, pt, pdt, tMax, t2);
        } else {
            *pt = tMax;
            *pdt = 0.0f < *pdt ? 0.0f : *pdt;
        }
    } else if (t < 0.0f) {
        if (*pdt < 0.0f)
            f = 1;
        if (p->grfapl & 8) {
            *pt = GModPositive(t, tMax);
        } else if (p->grfapl & 0x10) {
            float t2 = tMax + tMax;
            *pt = fmodf(-t, t2);
            PingPong(p, pt, pdt, tMax, t2);
        } else {
            *pt = 0.0f;
            *pdt = *pdt < 0.0f ? 0.0f : *pdt;
        }
    }
    return f;
}

